use vstd::prelude::*;

verus! {

fn reverse(a: &[i32]) -> (result: Vec<i32>)
    ensures
        result@.len() == a@.len(),
        forall|i: int|
            0 <= i < result@.len()
            ==> result@[i] == a@[result@.len() - 1 - i],
{
    let n: usize = a.len();
    let mut result: Vec<i32> = Vec::new();

    let mut i: usize = 0;
    while i < n
        invariant
            result@.len() == i as int,
            i <= n,
            forall|k: int|
                0 <= k < result@.len()
                ==> result@[k] == a@[n as int - 1 - k],
        decreases n - i,
    {
        // Safe because i < n in the loop guard
        let v = a[n - 1 - i];
        result.push(v);
        i = i + 1;
    }

    result
}

} // verus!

